from conceptgraph.completion.stage9 import OUTPUT as OLD,dump,digest
R=Path(__file__).resolve().parents[1];O=R/'annotation/quick_human_review_001'
def uri(p):return 'data:'+('image/png' if p.suffix=='.png' else 'image/jpeg')+';base64,'+base64.b64encode(p.read_bytes()).decode()
def main():
 O.mkdir(exist_ok=False);manifest_path=OLD/'visualizations/causal_development_review_002/review_manifest.json';manifest=json.loads(manifest_path.read_text());groups={}
 for c in manifest['cases']:groups.setdefault(c['scene'],[]).append(c)
 cards=[]
 for scene in sorted(groups):
  entries=sorted(groups[scene],key=lambda c:c['frame_idx']);entry=entries[len(entries)//2];p=OLD/entry['url'];e=json.loads(p.read_text())
